import {WEATHERTOP_POINTS as P,weathertopInteraction,drawWeathertopMap} from './weathertop-state.mjs';
export function createWeathertop(B,scene,world,{onMessage=()=>{},onChange=()=>{},onReturn=()=>{}}={}){
 const M=B.MeshBuilder,V=B.Vector3,root=new B.TransformNode('Weathertop region',scene),colliders=[],parts=[];
 const mat=(n,h,e=0)=>{const m=new B.StandardMaterial(n,scene);m.diffuseColor=B.Color3.FromHexString(h);m.specularColor.set(.03,.03,.03);if(e)m.emissiveColor=m.diffuseColor.scale(e);return m;};
 const earth=mat('Weathertop earth','#555d5b'),stone=mat('Weathered watchtower stone','#777c75'),slate=mat('Weathertop slate','#9a927f'),dark=mat('Wraith shadow','#11171c'),fireMat=mat('Old fire','#ff8a32',.9);
 const heightAt=(x,z)=>{const r=Math.hypot(x,z-7);return r>=28?0:7.2*Math.pow(1-r/28,1.15);};
 const ground=M.CreateGround('Weathertop colliding hillside',{width:98,height:99,subdivisions:48},scene);ground.parent=root;ground.material=earth;ground.checkCollisions=true;ground.isPickable=true;const pos=ground.getVerticesData(B.VertexBuffer.PositionKind),idx=ground.getIndices(),norm=[];for(let i=0;i<pos.length;i+=3)pos[i+1]=heightAt(pos[i],pos[i+2]);B.VertexData.ComputeNormals(pos,idx,norm);ground.setVerticesData(B.VertexBuffer.PositionKind,pos);ground.setVerticesData(B.VertexBuffer.NormalKind,norm);ground.refreshBoundingInfo();
 const box=(n,m,x,y,z,w,h,d)=>{const a=M.CreateBox(n,{width:w,height:h,depth:d},scene);a.material=m;a.position.set(x,y,z);a.parent=root;a.isPickable=false;parts.push(a);return a;};
 const ball=(n,m,x,y,z,sx,sy,sz)=>{const a=M.CreateSphere(n,{diameter:1,segments:8},scene);a.material=m;a.position.set(x,y,z);a.scaling.set(sx,sy,sz);a.parent=root;a.isPickable=false;parts.push(a);return a;};
 for(let i=0;i<24;i++){const z=-35+i*1.75,x=Math.sin(i*.62)*1.1,a=box('Broken slate trail',slate,x,heightAt(x,z)+.08,z,2.5,.12,1.35);a.rotation.y=Math.sin(i*1.7)*.12;}
 for(let i=0;i<10;i++){const a=i*Math.PI*2/10,x=Math.cos(a)*9.4,z=7+Math.sin(a)*9.4,h=2.2+(i%4)*.48,y=heightAt(x,z),p=box('Broken watchtower pillar',i%2?stone:dark,x,y+h/2,z,1,h,.9);p.rotation.z=Math.sin(i*2.4)*.1;const c=M.CreateBox('Weathertop pillar collider',{width:1,height:h,depth:.9},scene);c.position.set(x,y+h/2,z);c.parent=root;c.isVisible=false;c.checkCollisions=true;colliders.push(c);}
 const merged=B.Mesh.MergeMeshes(parts,true,true,undefined,false,false);merged.name='Batched Weathertop trail and ruins';merged.parent=root;merged.isPickable=false;merged.receiveShadows=true;
 const riderParts=[];const add=(n,x,y,z,sx,sy,sz)=>{const m=M.CreateSphere(n,{diameter:1,segments:8},scene);m.material=dark;m.position.set(x,y,z);m.scaling.set(sx,sy,sz);m.isPickable=false;riderParts.push(m);};
 add('Wraith horse body',0,.9,0,1.5,.6,.7);add('Wraith horse neck',0,1.45,.55,.4,.9,.35);add('Wraith horse head',0,1.95,.8,.45,.45,.4);add('Wraith rider cloak',0,2.55,-.1,.85,1.4,.65);add('Wraith rider hood',0,3.4,0,.5,.6,.48);
 const riders=B.Mesh.MergeMeshes(riderParts,true,true,undefined,false,false);riders.name='Mounted wraith silhouettes';riders.parent=root;riders.isPickable=false;riders.setEnabled(false);const matrices=new Float32Array(48);for(let i=0;i<3;i++){const a=i*Math.PI*2/3,m=B.Matrix.Compose(V.One(),B.Quaternion.Identity(),new V(Math.cos(a)*16,heightAt(Math.cos(a)*16,7+Math.sin(a)*16),7+Math.sin(a)*16));m.copyToArray(matrices,i*16);}riders.thinInstanceSetBuffer('matrix',matrices,16,true);riders.thinInstanceCount=3;
 const fireBase=box('Ancient fire ring',stone,0,heightAt(0,11)+.1,11,1.8,.25,1.8),flame=ball('Old fire flame',fireMat,0,heightAt(0,11)+.8,11,.5,1.1,.5),light=new B.PointLight('Weathertop firelight',new V(0,heightAt(0,11)+1.5,11),scene);light.parent=root;light.diffuse=B.Color3.FromHexString('#ff9a42');light.intensity=.15;light.range=18;
 for(const [x,z,w,d]of [[-48.5,0,1,98],[48.5,0,1,98],[0,-48.5,98,1],[0,48.5,98,1]]){const c=M.CreateBox('Weathertop boundary',{width:w,height:5,depth:d},scene);c.parent=root;c.position.set(x,2.5,z);c.isVisible=false;c.checkCollisions=true;colliders.push(c);}
 root.setEnabled(false);let active=false,state=null,clock=0,defense=0,hidden=[],oldColliders,oldGround,lighting;
 function activate(s,{resume=false}={}){state=s;active=true;oldColliders=world.colliders;oldGround=world.ground;lighting={fog:scene.fogMode,density:scene.fogDensity,color:scene.fogColor.clone(),clear:scene.clearColor.clone(),sun:world.sun.diffuse.clone(),sunIntensity:world.sun.intensity,hemi:world.hemi.intensity};const keep=new Set([world.body,...world.player.root.getChildMeshes(),...world.characters.filter(c=>['frodo','sam'].includes(c.id)).flatMap(c=>c.root.getChildMeshes())]);hidden=scene.meshes.filter(m=>m.isEnabled()&&!m.isDescendantOf(root)&&!keep.has(m));hidden.forEach(m=>m.setEnabled(false));for(const c of world.characters)if(!['frodo','sam','player'].includes(c.id))c.root.setEnabled(false);root.setEnabled(true);world.colliders=[...colliders,ground];world.ground=ground;scene.fogMode=B.Scene.FOGMODE_EXP2;scene.fogDensity=.021;scene.fogColor=B.Color3.FromHexString('#555e63');scene.clearColor=new B.Color4(.15,.19,.22,1);world.sun.diffuse.set(.55,.61,.68);world.sun.intensity=.38;world.hemi.intensity=.34;defense=state.defense||0;riders.setEnabled(['summit','defend'].includes(state.stage));if(!resume)reposition(P.entry.x,P.entry.z);else world.body.position.y=.72+heightAt(world.body.position.x,world.body.position.z);onChange();}
 function deactivate(){if(!active)return;active=false;root.setEnabled(false);hidden.forEach(m=>m.setEnabled(true));hidden=[];world.colliders=oldColliders;world.ground=oldGround;scene.fogMode=lighting.fog;scene.fogDensity=lighting.density;scene.fogColor.copyFrom(lighting.color);scene.clearColor.copyFrom(lighting.clear);world.sun.diffuse.copyFrom(lighting.sun);world.sun.intensity=lighting.sunIntensity;world.hemi.intensity=lighting.hemi;}
 function reposition(x,z){world.body.position.set(x,.72+heightAt(x,z),z);return world.body.position.clone();}
 function interactable(p){if(!active)return null;if(Math.hypot(p.x-P.return.x,p.z-P.return.z)<3.5)return {id:'weathertop-return',name:'عد إلى بري'};return weathertopInteraction(state,p);}
 function interact(){const item=interactable(world.body.position);if(!item)return false;if(item.id==='weathertop-return'){onReturn();return true;}if(item.id==='weathertop-summit'&&state.stage==='climb'){state.stage='summit';riders.setEnabled(true);onMessage('تظهر ظلال الفرسان حول أطلال المراقبة. اقترب من النار القديمة.');onChange();return true;}if(item.id==='weathertop-fire'&&state.stage==='summit'){state.stage='defend';defense=0;state.defense=0;light.intensity=2.4;onMessage('أشعلت النار. ابقَ قريبًا منها وثابتًا حتى تتراجع الظلال.');onChange();return true;}if(item.id==='weathertop-exit'&&state.stage==='escape'){state.stage='complete';state.defense=6;riders.setEnabled(false);onMessage('انحسر الظلام عن ويذرتوب. الطريق التالي نحو Rivendell.');onChange();return true;}return false;}
 function update(dt,{moving=false,paused=false}={}){if(!active)return;clock+=Math.max(0,Math.min(.2,dt));if(state.stage==='defend'&&!paused){const d=Math.hypot(world.body.position.x-P.fire.x,world.body.position.z-P.fire.z);defense=d<5.5&&!moving?Math.min(6,defense+dt):0;state.defense=defense;if(defense>=6){state.stage='escape';riders.setEnabled(false);light.intensity=1.2;onMessage('تراجعت الظلال. انزل من التل واجتمع برفاقك عند المدخل الجنوبي.');onChange();}}if(state.stage==='defend')light.intensity=2.2+Math.sin(clock*8)*.2;flame.scaling.y=1+Math.sin(clock*11)*.1;}
 function snapshot(){return {active,stage:state?.stage,defense:Math.round(defense*10)/10,wraithsVisible:riders.isEnabled(),height:heightAt(world.body.position.x,world.body.position.z),meshes:root.getChildMeshes().length};}
 return {activate,deactivate,interact,interactable,update,reposition,snapshot,get active(){return active;},get ground(){return ground;},drawMap:(canvas,p)=>drawWeathertopMap(canvas,p,state)};
}
